CREATE TABLE IF NOT EXISTS ai_runs (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,plugin_id text NOT NULL,status text NOT NULL,candidates jsonb NOT NULL DEFAULT '[]',selected_id text,cost numeric(10,4) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS interactive_sessions (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,plugin_id text NOT NULL,state text NOT NULL,snapshot jsonb NOT NULL DEFAULT '{}',share_token text UNIQUE,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS video_renders (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,plugin_id text NOT NULL,status text NOT NULL,output_key text,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS experiment_variants (id uuid PRIMARY KEY,plugin_id text NOT NULL,status text NOT NULL,config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS message_subscriptions (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,event_type text NOT NULL,status text NOT NULL,scheduled_at timestamptz,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS physical_orders (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,work_id uuid REFERENCES works(id),sku text NOT NULL,address jsonb NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,plan text NOT NULL,status text NOT NULL,quota integer NOT NULL,used integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS annual_reports (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,year integer NOT NULL,status text NOT NULL,output_key text,created_at timestamptz NOT NULL,UNIQUE(user_id,year));
